9	 * {@code namesakeCount} is 0, adds 2 for a household of 3 or more members and adds 3 for tenure of
10	 * more than one elapsed fiscal year.
11	 */
12	public final class MembershipPoints {
13	
14	    private MembershipPoints() {
15	    }
16	
17	    public static int of(Owner owner, int namesakeCount, int householdSize) {
18	        int points = 0;
19	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
20	            points += 2;
21	        }
22	        if (namesakeCount == 0) {
23	            points += 1;
24	        }
25	        if (householdSize >= 3) {
26	            points += 2;
27	        }
28	        if (Tenure.fiscalYears(owner) > 1) {
29	            points += 3;
30	        }
31	        return points;
32	    }
33	
34	    private static final class Tenure {
35	        static int fiscalYears(Owner owner) {
36	            LocalDate registration = owner.getRegistrationDate();
37	            return registration == null ? 0 : FiscalYear.of(LocalDate.now()) - FiscalYear.of(registration);
38	        }
39	    }
40	}
