3	import java.util.concurrent.atomic.AtomicLong;
4	
5	import org.slf4j.Logger;
6	import org.slf4j.LoggerFactory;
7	
8	import net.officefloor.plugin.variable.Val;
9	import org.springframework.samples.petclinic.model.Owner;
10	import org.springframework.samples.petclinic.repository.OwnerRepository;
11	
12	public class SaveOwner {
13	
14	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
15	
16	    private static final AtomicLong EVENT_SEQ = new AtomicLong();
17	
18	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
19	        ownerRepository.save(owner);
20	        int namesakeCount = NamesakeCount.of(owner, ownerRepository);
21	        int membershipLevel = MembershipLevel.of(
22	            MembershipPoints.of(owner, namesakeCount, HouseholdSize.of(owner, ownerRepository)));
23	        String membershipNumber = owner.getCustomerCode() + "-M" + FiscalYear.yy(owner);
24	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
25	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), membershipLevel, membershipNumber);
26	        // Immutable structured event. Carries the owner's current primary identifier
27	        // (customerCode today, the memberId once that is unified) as the customerCode field.
28	        String event = String.format(
29	            "{\"seq\":%d,\"ownerId\":%d,\"customerCode\":\"%s\",\"membershipLevel\":%d,\"event\":\"OWNER_CREATED\"}",
30	            EVENT_SEQ.incrementAndGet(), owner.getId(), owner.getCustomerCode(), membershipLevel);
31	        AUDIT.info("{}", event);
32	    }
33	}
