4	import static org.junit.jupiter.api.Assertions.assertTrue;
5	import tools.jackson.databind.JsonNode;
6	
7	/** member-id: customerCode and membershipNumber are unified into 'memberId' =
8	 * '<REGION><FY><HASH8><CHK>'. Assert the exact, computable sub-values: the pinned region prefix and
9	 * the SHA-256 HASH8 over (telephone + lastName); and that the two old fields are gone. */
10	class AcceptanceTest extends AcceptanceBase {
11	
12		@Test
13		void coreReturnsUnifiedMemberId() throws Exception {
14			JsonNode r = fetchOwner(createOwnerOk(knownOwner("Sydney"))); // region NSW
15			String hash8 = shaHex(r.get("telephone").asText() + r.get("lastName").asText(), 8);
16			String memberId = r.get("memberId").asText();
17			assertTrue(memberId.startsWith("NSW"), memberId);
18			assertTrue(memberId.contains(hash8), memberId + " should contain " + hash8);
19			assertTrue(!r.has("customerCode") && !r.has("membershipNumber"), "old id fields removed");
20		}
21	}
